{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Gentle intensive sessions for pivotal moments</title>
  <meta name="description" content="Intensive, focused therapeutic work for life transitions and moments that matter. Short-term intensives, steady planning, and clear next steps." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-mystic">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="22" fill="rgba(255,255,255,0.06)" stroke="rgba(255,255,255,0.12)"/></svg>
      <div>
        <strong class="business">{{BUSINESS_NAME}}</strong>
        <div class="tag">{{TAGLINE}}</div>
      </div>
    </div>
    <nav class="site-nav" aria-label="Primary">
      <a href="index.html">Welcome</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">Way I Work</a>
      <a href="fees.html">Invest</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html" class="accent">Begin</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero glass">
      <div class="hero-inner">
        <h1>Focused intensives for the moments you need clarity</h1>
        <p class="lead">Sessions shaped around a current pressure—so you leave with a steadier plan, kinder perspective, and practical next steps. Sessions are collaborative, time-bound, and tailored to your priorities.</p>
        <div class="hero-cta">
          <a id="primary-cta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn outline" href="book.html">See session types</a>
        </div>
      </div>
      <div class="hero-pattern" aria-hidden="true"></div>
    </section>

    <section class="social-proof">
      <div class="card glass">
        <strong class="quote">"Direct, calm, and unexpectedly freeing."
          <span class="meta">— a recent intensive client, {{CITY}}, {{STATE}}</span>
        </strong>
        <div class="small">Clinical practice — confidential, evidence-informed, individually tailored work.</div>
      </div>
    </section>

    <section class="benefits glass" id="benefits">
      <h2>What an intensive can do</h2>
      <ul>
        <li><strong>Clarify a priority:</strong> short, practical framing that reduces decision fog.</li>
        <li><strong>Map next moves:</strong> stepwise plans you can try without perfection.</li>
        <li><strong>Stabilize an urgent moment:</strong> calm the most pressing stressors and identify supports.</li>
      </ul>
    </section>

    <section class="process glass" id="method">
      <h2>Mood-to-Method</h2>
      <p class="muted">Choose how you feel now; get a suggested session approach and a tailored CTA.</p>

      <div class="mood-row">
        <div class="mood-selector">
          <label><input type="radio" name="mood" value="navigation" checked> Overloaded / Need a plan</label>
          <label><input type="radio" name="mood" value="anchor"> Anxious / Need grounding</label>
          <label><input type="radio" name="mood" value="reflection"> Stuck / Want clearer meaning</label>
          <label><input type="radio" name="mood" value="focus"> Practical choice / Quick decisions</label>
        </div>

        <div class="method-card" id="method-card">
          <div class="method-badge">Recommended</div>
          <h3 id="method-title">Focused Planning Intensive</h3>
          <p id="method-desc">A time-limited session that maps the core pressures, names the smallest next step, and arranges short checkpoints so the plan is doable.</p>
          <div class="method-actions">
            <a id="method-cta" class="btn" href="{{PRIMARY_CTA_URL}}">Book a Planning Intensive</a>
            <a class="btn outline" href="book.html">Compare offerings</a>
          </div>
        </div>
      </div>
    </section>

    <section class="faq glass" id="faq">
      <h2>Short questions, clear answers</h2>
      <div class="qa">
        <details>
          <summary>How long is an intensive?</summary>
          <p>Most intensives are 90–120 minutes. A plan for follow-up is included when useful. We will discuss scope before booking.</p>
        </details>
        <details>
          <summary>Do you offer remote sessions?</summary>
          <p>Yes. Telehealth is available; location-specific considerations (licensing, emergency contacts) will be addressed when you book.</p>
        </details>
      </div>
    </section>

    <section class="cta-block glass">
      <h2>Ready to begin a focused session?</h2>
      <p class="muted">Choose an approach above, then follow the tailored link. If you prefer, reach out for a brief intake conversation.</p>
      <div class="cta-actions">
        <a id="primary-cta-2" class="btn large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn outline" href="contact.html">Email: {{EMAIL}}</a>
      </div>
    </section>

    <section class="confidentiality glass" id="confidentiality">
      <h2>Session boundaries & confidentiality</h2>
      <div class="accordion">
        <div class="item">
          <button class="accordion-toggle" aria-expanded="false">Session boundaries</button>
          <div class="panel">
            <p>Sessions are scheduled and time-limited. Please arrive on time so we can make the most of our work together. If you need to reschedule, please let us know as soon as possible so that the session time can be offered to another client.</p>
            <p>Therapy is a collaborative process focused on your goals. We will discuss what to expect at the outset and revisit boundaries and scope as your needs evolve.</p>
          </div>
        </div>

        <div class="item">
          <button class="accordion-toggle" aria-expanded="false">Confidentiality and limits</button>
          <div class="panel">
            <p>Your privacy is treated with professional care. Notes and communications are stored securely. Confidentiality may be limited by law in situations such as clear risk of harm to self or others, or legal requirements; these limits will be discussed explicitly when relevant.</p>
            <p>For detailed policies, ask for a copy of the practice agreement or see the intake materials before our first session.</p>
          </div>
        </div>
      </div>
      <div class="crisis-note">
        <strong>If you are in immediate danger:</strong> contact local emergency services right away. If you are in the United States and experiencing a mental health crisis, you can call or text 988 for the Suicide & Crisis Lifeline. If you are outside the U.S., please follow local emergency guidance.
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
      <div>Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
    <small class="muted">Licensed clinician. Sessions are not a substitute for emergency care. No guarantees made; therapy offers supportive, evidence-informed guidance tailored to your experience.</small>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
