{"path":"assets/css/styles.css","content":"/* Glass-morphism + mystic-modern palette */
:root{--bg:#0f1720;--card:#0f172020;--glass-border:rgba(255,255,255,0.06);--accent:#86efac;--muted:rgba(255,255,255,0.65);--glass:#ffffff08}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial; background:linear-gradient(180deg,#07101A 0%, #07121B 60%), url('../assets/img/pattern.svg'); background-size:600px 600px; color:#e7eef6}
.theme-mystic a{color:var(--accent)}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
.brand{display:flex;align-items:center;gap:12px}
.brand .logo{width:44px;height:44px}
.business{display:block;font-weight:700}
.tag{font-size:12px;color:var(--muted)}
.site-nav a{color:var(--muted);margin-left:14px;text-decoration:none;padding:6px 8px;border-radius:6px}
.site-nav a.accent{background:linear-gradient(90deg,#0f1720, #0f2a3a);border:1px solid rgba(255,255,255,0.04)}
main{max-width:980px;margin:28px auto;padding:0 22px}
.glass{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid var(--glass-border);backdrop-filter: blur(8px);border-radius:12px;padding:20px;margin:18px 0}
.hero{display:grid;grid-template-columns:1fr 220px;gap:18px;align-items:center;padding:28px}
.hero .lead{color:var(--muted);margin-top:8px}
.hero-cta{margin-top:16px}
.btn{display:inline-block;background:linear-gradient(90deg,#2EE6A2,#69D4FF);color:#022229;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.outline{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
.btn.large{padding:14px 20px;font-size:18px}
.hero-pattern{width:100%;height:120px;border-radius:8px;justify-self:end;background:rgba(255,255,255,0.02);box-shadow:inset 0 0 40px rgba(0,0,0,0.4)}
.social-proof .card{padding:14px}
.quote{font-style:italic}
.quote .meta{display:block;font-size:12px;color:var(--muted);margin-top:8px}
.benefits ul{list-style:none;padding:0;margin:0}
.benefits li{padding:8px 0;border-bottom:1px dashed rgba(255,255,255,0.02)}
.process .mood-row{display:flex;gap:18px;align-items:flex-start}
.mood-selector{display:flex;flex-direction:column;gap:8px;padding:10px}
.mood-selector label{background:rgba(255,255,255,0.01);padding:10px;border-radius:8px;cursor:pointer}
.method-card{flex:1;padding:16px;border-radius:12px;background:linear-gradient(180deg,#0f2230 0%, #0b1620 100%);border:1px solid rgba(255,255,255,0.03)}
.method-badge{font-size:12px;color:var(--muted);margin-bottom:8px}
.method-actions{margin-top:12px}
.faq details{background:rgba(255,255,255,0.01);padding:10px;border-radius:8px;margin-bottom:8px}
.confidentiality .accordion .item{margin-bottom:10px}
.accordion-toggle{width:100%;text-align:left;padding:12px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.03);color:var(--muted);cursor:pointer}
.panel{padding:12px;display:none;color:var(--muted)}
.panel.open{display:block}
.crisis-note{margin-top:10px;padding:12px;background:linear-gradient(90deg,rgba(255,65,65,0.06),rgba(255,255,255,0.01));border-radius:8px;color:#ffdcdc}
.site-footer{padding:18px 28px;color:var(--muted);border-top:1px solid rgba(255,255,255,0.02);display:flex;justify-content:space-between}
.small{font-size:13px;color:var(--muted)}
@media (max-width:820px){
  .hero{grid-template-columns:1fr;}
  .process .mood-row{flex-direction:column}
  .site-nav{display:none}
  .hero-pattern{height:100px}
}
/* subtle focus styles */
:focus{outline:2px solid rgba(134,239,172,0.22);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Mood-to-Method mapping
  const mapping = {
    navigation: {
      title: 'Focused Planning Intensive',
      desc: 'We identify the immediate pressures, map options, and craft the smallest feasible next step to reduce overwhelm.',
      ctaText: 'Book a Planning Intensive',
      ctaSuffix: 'planning'
    },
    anchor: {
      title: 'Stabilization & Grounding Session',
      desc: 'Tools and short exercises to settle the body and mind, plus a brief plan for managing spikes between sessions.',
      ctaText: 'Book a Grounding Session',
      ctaSuffix: 'grounding'
    },
    reflection: {
      title: 'Exploratory Insight Intensive',
      desc: 'A reflective session that helps name patterns and clarifies meaning so you can make considered changes with less friction.',
      ctaText: 'Book an Insight Intensive',
      ctaSuffix: 'insight'
    },
    focus: {
      title: 'Decision-Focused Session',
      desc: 'A concentrated session for comparing options, weighing values, and leaving with a concrete action plan you can try right away.',
      ctaText: 'Book a Decision Session',
      ctaSuffix: 'decision'
    }
  };

  const radios = document.querySelectorAll('input[name="mood"]');
  const titleEl = document.getElementById('method-title');
  const descEl = document.getElementById('method-desc');
  const methodCta = document.getElementById('method-cta');
  const primaryCta = document.getElementById('primary-cta');
  const primaryCta2 = document.getElementById('primary-cta-2');

  function applyMood(mood){
    const m = mapping[mood] || mapping.navigation;
    titleEl.textContent = m.title;
    descEl.textContent = m.desc;
    // update CTAs: respectful phrasing
    methodCta.textContent = m.ctaText;
    methodCta.setAttribute('data-suffix', m.ctaSuffix);
    // compose a friendly CTA label for main CTA buttons
    if(primaryCta){
      primaryCta.textContent = m.ctaText.replace(/^Book /i, 'Request ');
    }
    if(primaryCta2){
      primaryCta2.textContent = m.ctaText;
    }
  }

  radios.forEach(r=>{
    r.addEventListener('change',function(e){
      if(e.target.checked){
        applyMood(e.target.value);
      }
    });
  });

  // initialize
  const checked = document.querySelector('input[name="mood"]:checked');
  if(checked) applyMood(checked.value);

  // Accordion controls for confidentiality section
  const toggles = document.querySelectorAll('.accordion-toggle');
  toggles.forEach(btn=>{
    btn.addEventListener('click', function(){
      const expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      const panel = this.nextElementSibling;
      if(!expanded){ panel.classList.add('open'); }
      else { panel.classList.remove('open'); }
    });
  });

  // A11y: allow keyboard toggles
  toggles.forEach(btn=>{
    btn.addEventListener('keydown', function(e){
      if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); this.click(); }
    });
  });

  // Enhancement: method CTA leads to booking with mood hint in hash
  const methodLink = document.getElementById('method-cta');
  methodLink.addEventListener('click', function(e){
    const suffix = this.getAttribute('data-suffix') || 'plan';
    // append a short fragment so intake form can read mood hint
    this.href = this.getAttribute('href').split('#')[0] + '#mood=' + encodeURIComponent(suffix);
  });

  // keep primary CTA consistent
  [primaryCta, primaryCta2].forEach(el=>{
    if(!el) return;
    el.addEventListener('click', function(){
      // no telem, just a gentle style change on click
      this.classList.add('clicked');
      setTimeout(()=>this.classList.remove('clicked'),600);
    });
  });

});"} 
